const path = require('path');
const fs = require('fs');
const os = require('os');
const { execSync } = require('child_process');

// --- Konfigurasi ---
// 5 menit per chunk => Whisper selesai ~40-50s => aman di bawah 120s proxy timeout
// HTTP Request node n8n menjalankan semua item secara paralel (Promise.allSettled),
// sehingga N chunk berjalan bersamaan. Dengan chunk 5 menit masing-masing selesai
// jauh sebelum timeout, ini aman untuk audio hingga 4 jam (MAX_CHUNKS=30 x 5 menit).
const CHUNK_SECONDS = 300;  // 5 menit per chunk
const MAX_CHUNKS    = 30;   // max ~2.5 jam audio
const BITRATE       = '32k'; // naik dari 16k: akurasi lebih baik, ukuran ~2x (5 menit ~1.2 MB)

const item = $input.first();
const binaryKey = 'recording';
if (!item.binary || !item.binary[binaryKey]) {
  throw new Error('No recording binary data found');
}
const binaryData = item.binary[binaryKey];
const origName   = binaryData.fileName || 'recording.mp4';
const ts         = Date.now();

// Direktori unik per eksekusi â€” terisolasi
const tmpDir = path.join(os.tmpdir(), 'n8n_mtg_' + ts).replace(/\\/g, '/');
fs.mkdirSync(tmpDir, { recursive: true });

let inputFile;
const out = [];

try {
  if (binaryData.id && String(binaryData.id).startsWith('filesystem-v2:')) {
    // File sudah di disk (filesystem binary mode) â€” akses langsung, 0 alokasi RAM ekstra
    const rel = String(binaryData.id).replace('filesystem-v2:', '');
    inputFile = path.join(os.homedir(), '.n8n', 'binaryData', rel).replace(/\\/g, '/');
  } else {
    // In-memory base64 â€” decode dan tulis ke tmpDir
    // MEMORY NOTE: decode ~1.33x ukuran base64; untuk 1 jam video ~50-150 MB sementara.
    // Aktifkan N8N_DEFAULT_BINARY_DATA_MODE=filesystem untuk menghindari ini pada file besar.
    const buffer = Buffer.from(binaryData.data, 'base64');
    const ext = path.extname(origName) || '.mp4';
    inputFile = path.join(tmpDir, 'input' + ext).replace(/\\/g, '/');
    fs.writeFileSync(inputFile, buffer);
  }

  const fileSizeMB  = (fs.statSync(inputFile).size / 1024 / 1024).toFixed(2);
  const outPattern  = path.join(tmpDir, 'chunk_%03d.mp3').replace(/\\/g, '/');

  // Satu pass: konversi + segmentasi
  execSync(
    'ffmpeg -i "' + inputFile + '" -vn -ar 16000 -ac 1 -b:a ' + BITRATE +
    ' -f segment -segment_time ' + CHUNK_SECONDS + ' "' + outPattern + '" -y',
    { timeout: 600000, stdio: 'pipe' }
  );

  const chunkFiles = fs.readdirSync(tmpDir)
    .filter(f => f.startsWith('chunk_') && f.endsWith('.mp3'))
    .sort();

  if (chunkFiles.length === 0) throw new Error('ffmpeg menghasilkan 0 chunk');
  if (chunkFiles.length > MAX_CHUNKS) {
    throw new Error('Audio terlalu panjang: ' + chunkFiles.length + ' chunk, batas ' +
      MAX_CHUNKS + ' (~' + (MAX_CHUNKS * CHUNK_SECONDS / 60).toFixed(0) + ' menit max)');
  }

  const baseName = origName.replace(/\.[^/.]+$/, '');
  chunkFiles.forEach((fname, idx) => {
    const buf = fs.readFileSync(path.join(tmpDir, fname).replace(/\\/g, '/'));
    out.push({
      json: {
        meeting_name:       item.json.meeting_name || '',
        originalFileName:   origName,
        originalFileSizeMB: parseFloat(fileSizeMB),
        chunk_index:        idx,
        total_chunks:       chunkFiles.length
      },
      binary: {
        recording: {
          data:     buf.toString('base64'),
          mimeType: 'audio/mpeg',
          fileName: baseName + '_chunk' + String(idx).padStart(3, '0') + '.mp3',
          fileSize: buf.length
        }
      }
    });
  });
} finally {
  // Selalu bersihkan tmpDir, termasuk saat error
  try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch(_) {}
}

return out;

const items = $input.all();

if (items.length === 0) {
  throw new Error('Merge Transcripts: tidak ada hasil dari Whisper');
}

// Ambil expected total_chunks dari Audio Conversion (semua chunk punya nilai sama)
let expectedTotal = null;
try { expectedTotal = $('Audio Conversion').first().json.total_chunks; } catch(_) {}

// Validasi 1: jumlah hasil harus sesuai
if (expectedTotal != null && items.length !== expectedTotal) {
  throw new Error(
    'Jumlah hasil Whisper (' + items.length + ') != jumlah chunk (' + expectedTotal + ')'
  );
}

// Bangun data chunk dengan chunk_index via itemMatching dari Audio Conversion
const chunkData = [];
for (let i = 0; i < items.length; i++) {
  let chunkIdx = i; // fallback ke sequential index
  try {
    const acItem = $('Audio Conversion').itemMatching(i);
    if (acItem && acItem.json != null && acItem.json.chunk_index != null) {
      chunkIdx = acItem.json.chunk_index;
    }
  } catch(_) { /* gunakan fallback */ }

  const raw = items[i].json;
  const text = (raw && typeof raw.text === 'string') ? raw.text : '';
  chunkData.push({ idx: chunkIdx, text });
}

// Sort berdasarkan chunk_index
chunkData.sort((a, b) => a.idx - b.idx);

// Validasi 2: indices kontigu dari 0 sampai N-1
for (let i = 0; i < chunkData.length; i++) {
  if (chunkData[i].idx !== i) {
    const got = chunkData.map(c => c.idx).join(',');
    throw new Error('chunk_index tidak kontigu â€” expected ' + i + ', got [' + got + ']');
  }
}

// Validasi 3: tidak ada chunk kosong
for (const c of chunkData) {
  if (!c.text || c.text.trim() === '') {
    throw new Error('Chunk ' + c.idx + ' menghasilkan transkrip kosong');
  }
}

const fullText = chunkData.map(c => c.text.trim()).join(' ');

return [{
  json: {
    text: fullText,
    total_chunks: chunkData.length,
    merge_status: 'complete'
  },
  pairedItem: { item: 0 }
}];
